#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    long long minOperations(vector<int>& a){
        int n=a.size();unordered_map<int,int>freq;for(int x:a)freq[x]++;
        if(freq.size()==1)return 0;
        vector<int>pr;
        for(int i=2;i<=31623;i++){
            bool ok=true;for(int p:pr){if(1LL*p*p>i)break;if(i%p==0){ok=false;break;}}
            if(ok)pr.push_back(i);
        }
        unordered_map<int,int>multiple;
        unordered_map<int,vector<int>>divs;
        for(auto &it:freq){
            int x=it.first,z=x;vector<pair<int,int>>f;
            for(int p:pr){if(1LL*p*p>z)break;if(z%p==0){int e=0;while(z%p==0)z/=p,e++;f.push_back({p,e});}}
            if(z>1)f.push_back({z,1});
            vector<int>d(1,1);
            for(auto &pe:f){int len=d.size(),mul=1;
                for(int j=1;j<=pe.second;j++){mul*=pe.first;for(int k=0;k<len;k++)d.push_back(d[k]*mul);}
            }
            divs[x]=d;
            for(int v:d)multiple[v]+=it.second;
        }
        long long ans=n;
        for(auto &it:freq){
            int x=it.first;if(x==1)continue;
            long long dividing=0;
            for(int d:divs[x])if(freq.count(d))dividing+=freq[d];
            long long equal=it.second;
            long long cost=2LL*n-multiple[x]-dividing;
            // Equal elements were subtracted twice, but should cost zero.
            ans=min(ans,cost);
        }
        return ans;
    }
};
